import requests
for pmid in ['25450186','23393131','24804016','12194822']:
 u='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi'
 r=requests.get(u,params={'db':'pubmed','id':pmid,'retmode':'json'},timeout=20)
 print('PMID',pmid,'status',r.status_code)
 try:
  x=r.json()['result'][pmid]; print(x.get('title'),x.get('pubdate'),x.get('fulljournalname'),x.get('elocationid'))
 except Exception as e: print(r.text[:200])
